const views = {
  exposure: {label:'EXPOSURE INTELLIGENCE',title:'See how the<br>pieces connect.',description:'Explore attack paths alongside identity, cloud and infrastructure posture. Move from an isolated finding to the environment around it.',list:['Adversarial exposure graph','Cloud and identity security','Software supply chain posture'],preview:'Exposure overview',stats:['Attack paths','08','to investigate','Affected assets','24','in this example'],heading:'Priority signals',rows:['Public workload → privileged role','Cloud configuration exposure','Dependency requires review'],badges:['Identity','Cloud','Supply chain']},
  validate: {label:'SECURITY CONTROL VALIDATION',title:'Look closer at<br>your defenses.',description:'Review control assessments, failed checks and agent health together. Inspect the evidence behind a result and the assets it affects.',list:['Control assessment results','Agent coverage and health','Evidence and remediation guidance'],preview:'Control validation',stats:['Checks evaluated','42','example control','Failed checks','03','require review'],heading:'Assessment evidence',rows:['Endpoint protection check failed','Agent health requires attention','Validation evidence available'],badges:['Failed check','Agent health','Evidence']},
  prioritize: {label:'RISK & INVESTIGATION',title:'Give every finding<br>a place in the picture.',description:'Investigate findings with their history and affected assets. Bring organizational risk and technical details into the same conversation.',list:['Organizational Risk Index','Finding triage and history','Financial risk perspective'],preview:'Investigation workspace',stats:['Open findings','12','example cohort','Risk index','64','illustrative score'],heading:'Investigation queue',rows:['Exposed asset needs investigation','Identity permissions under review','Control finding ready for triage'],badges:['Open','In progress','Open']}
};
const tabs = [...document.querySelectorAll('[role=tab]')];
function selectTab(tab){const view=views[tab.dataset.view];tabs.forEach(item=>{item.setAttribute('aria-selected',String(item===tab));item.tabIndex=item===tab?0:-1;});document.querySelector('#platform-panel').setAttribute('aria-labelledby',tab.id);document.querySelector('#panel-label').textContent=view.label;document.querySelector('#panel-title').innerHTML=view.title;document.querySelector('#panel-description').textContent=view.description;document.querySelector('#panel-list').replaceChildren(...view.list.map(text=>{const li=document.createElement('li');li.textContent=text;return li;}));document.querySelector('#preview-title').textContent=view.preview;document.querySelector('#stat-one-label').textContent=view.stats[0];document.querySelector('#stat-two-label').textContent=view.stats[3];['one','two'].forEach((n,i)=>{const strong=document.querySelector('#stat-'+n);const detail=document.createElement('span');detail.textContent=view.stats[i*3+2];strong.replaceChildren(document.createTextNode(view.stats[i*3+1]),detail);});document.querySelector('#row-heading').textContent=view.heading;['one','two','three'].forEach((n,i)=>{document.querySelector('#row-'+n).textContent=view.rows[i];document.querySelector('#badge-'+n).textContent=view.badges[i];});}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectTab(tab));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%tabs.length;if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=tabs.length-1;if(next!==undefined){event.preventDefault();selectTab(tabs[next]);tabs[next].focus();}});});
document.querySelector('#year').textContent=String(new Date().getFullYear());
